// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        address owner1;
        address owner2;
        vm.prank(caller1);
        owner1 = c.owner();
        vm.prank(caller2);
        owner2 = c.owner();
        assertTrue(owner1 == owner2, "owner() should return same value for all callers");
    }
}
